/* Group approval business migrated from zhongtai; PC owns rendering and storage. */
(function(){
'use strict';
const A=GA,E=A.E,F=E.F,C=A.config,{esc,btn,input,select,textarea,check,opts}=A;
const O=A.oa={},state=()=>A.state,draft=()=>C.editor.draft;
let selected='',owner=null,device='phone',past=[],future=[],advancedTab='process',nodeTab='people',nodeEdit=null,nodeCtx=null,groupFilter='',query='',batch=false,chosen=new Set();
const panel=(title,body)=>`<section class="oa-section"><h3>${title}</h3>${body}</section>`;
const options=(rows,values,name)=>`<div class="ga-checkboxes">${rows.map(([id,label])=>`<label><input type="checkbox" name="${esc(name)}" value="${esc(id)}" ${values?.includes(id)?'checked':''}>${esc(label)}</label>`).join('')}</div>`;
const setting=(label,name,value,hint='')=>`<div class="oa-switch-row"><span>${label}${hint?`<small>${hint}</small>`:''}</span><label class="switch"><input type="checkbox" name="${esc(name)}" aria-label="${esc(label)}" ${value?'checked':''} role="switch"></label></div>`;
function sync(){if(owner!==C.editor){owner=C.editor;selected=draft().fields[0]?.id||'';past=[];future=[];}}
O.remember=history;
function history(){past.push(E.clone(draft().fields));if(past.length>40)past.shift();future=[];const undo=document.querySelector('[data-action=oa-undo]'),redo=document.querySelector('[data-action=oa-redo]');if(undo)undo.disabled=false;if(redo)redo.disabled=true;}
function field(){return draft().fields.find(f=>f.id===selected);}
function captureField(){const form=document.querySelector('#oa-field-properties'),f=field();if(!form||!f)return;const fd=new FormData(form);for(const el of form.querySelectorAll('input[name]:not([name^="_pc-"]),select[name],textarea[name]')){const k=el.name;if(k==='scopePeople'||k==='options'||k==='columns'||k==='conditionField'||k==='conditionValue')continue;if(el.type==='checkbox')f[k]=el.checked;else if(el.type==='number')f[k]=el.value===''?'':Number(el.value);else f[k]=el.value;}if(f.type==='person')f.scope=fd.getAll('scopePeople');if(fd.has('options'))f.options=String(fd.get('options')).split('\n').map(x=>x.trim()).filter(Boolean);if(fd.has('columns')){const lines=String(fd.get('columns')).split('\n').map(x=>x.trim()).filter(Boolean);f.columns=lines.map((line,i)=>{const [label,type='text',required='必填']=line.split('|').map(x=>x.trim());return {id:f.columns?.[i]?.id||E.id('col'),label,type:['number','money'].includes(type)?type:'text',required:required!=='选填'};});}if(fd.has('conditionField'))f.showWhen=fd.get('conditionField')?{field:fd.get('conditionField'),value:fd.get('conditionValue')}:null;if(['multiselect','person','department'].includes(f.type)&&f.multiple||f.type==='multiselect')f.defaultValue=String(fd.get('defaultValue')||'').split('\n').map(x=>x.trim()).filter(Boolean);}
function captureBasic(d){const form=document.querySelector('#rule-basic');if(!form)return;const fd=new FormData(form);d.basic.initiatorMode=fd.get('initiatorMode');d.basic.initiators=fd.get('initiatorMode')==='selected'?fd.getAll('initiators'):[];d.basic.adminMode=fd.get('adminMode');d.basic.admins=fd.get('adminMode')==='selected'?fd.getAll('admins'):[];d.basic.icon=fd.get('icon')||'list';}
function captureAdvanced(d){const form=document.querySelector('#oa-settings');if(!form)return;const fd=new FormData(form),s=d.settings;for(const el of form.querySelectorAll('input[data-setting],select[data-setting],textarea[data-setting]')){const k=el.name;if(el.type==='radio'&&!el.checked)continue;s[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;}if(fd.has('summaryMarker'))s.summaryFields=fd.getAll('summaryFields');if(fd.has('permissionMarker')){s.permissions=Array.from(form.querySelectorAll('[data-permission]')).map(el=>{const id=el.dataset.permission;return {id,name:fd.get('permissionName:'+id),members:fd.getAll('permissionMembers:'+id),scope:fd.get('permissionScope:'+id),view:fd.has('permissionView:'+id),export:fd.has('permissionExport:'+id)};});}}
O.capture=d=>{captureField();captureBasic(d);captureAdvanced(d);};
O.basicView=d=>`<div class="oa-basic"><form id="rule-basic"><div class="oa-basic-name">${input('<span class="ga-required">*</span>表单名称','name',d.basic.name,'maxlength="50"')}</div>${select('所在分组','category',state().categories.map(c=>[c.id,c.name]),d.basic.category)}${textarea('表单说明','description',d.basic.description,'maxlength="100" placeholder="说明表单用途和填写要求"')}${panel('谁可以发起',select('成员范围','initiatorMode',[['all','全部成员'],['selected','指定成员']],d.basic.initiatorMode||(d.basic.initiators?.length?'selected':'all'))+`<div data-basic-members ${d.basic.initiatorMode==='selected'||d.basic.initiators?.length?'':'hidden'}>${options(C.people(),d.basic.initiators||[],'initiators')}</div>`)}${panel('适用公司与部门',check('全部公司','allCompanies',d.basic.companies.includes('*'))+`<div id="company-checks" ${d.basic.companies.includes('*')?'hidden':''}>${C.checks('companies',C.allCompanies(),d.basic.companies)}</div>`+check('公司范围内的全部部门','allDepartments',!d.basic.departments?.length)+`<div id="department-checks" ${d.basic.departments?.length?'':'hidden'}>${C.checks('departments',C.departments(),d.basic.departments||[])}</div>`)}${panel('表单管理员',select('管理成员','adminMode',[['all','全部集团审批管理员'],['selected','指定集团审批管理员']],d.basic.adminMode||(d.basic.admins?.length?'selected':'all'))+`<div data-basic-admins ${d.basic.adminMode==='selected'||d.basic.admins?.length?'':'hidden'}>${options(C.people().filter(([id])=>E.admin(state(),id)),d.basic.admins||[],'admins')}</div>`)}<p class="ga-helper">公司、部门与指定成员范围同时满足时可发起；管理员负责配置，不代替节点审批人处理申请。</p><p class="oa-id">表单 ID：${esc(C.editor.id)}</p></form></div>`;
function propertyView(f){if(!f)return '<div class="oa-property-empty">选择表单中的控件<br>在这里配置它的属性</div>';const numeric=['number','money','formula','rating'].includes(f.type),common=['text','textarea','number','money','select','multiselect','cascade','phone','idcard','related','person'].includes(f.type);let content=input('标题','label',f.label,'maxlength="50"')+(common?input('提示文字','placeholder',f.placeholder||'','maxlength="50"'):'')+input('字段说明','help',f.help||'','maxlength="200"');
if(f.type==='multiselect')content+=textarea('默认选项','defaultValue',(F.list(f.defaultValue)).join('\n'),'placeholder="每行填写一个选项"');if(['text','textarea','number','money','select','date'].includes(f.type))content+=input(f.type==='multiselect'?'默认值（单个选项）':'默认值','defaultValue',Array.isArray(f.defaultValue)?f.defaultValue.join('\n'):f.defaultValue??'','',f.type==='date'?f.dateFormat||'date':'text');
if(['select','multiselect','cascade'].includes(f.type))content+=panel('选项设置',textarea('选项内容','options',(f.options||[]).join('\n'),'rows="5"')+'<p class="ga-helper">每行一个选项；级联选项用 / 分隔层级。</p>'+setting('选项平铺','inline',f.inline)+(['multiselect'].includes(f.type)?input('最少选择项','minCount',f.minCount||0,'min="0"','number')+input('最多选择项','maxCount',f.maxCount||50,'min="1" max="50"','number'):''));
if(['text','textarea'].includes(f.type))content+=panel('填写校验',input('最少字数','minLength',f.minLength||'','min="0"','number')+input('最多字数','maxLength',f.maxLength||'','min="1"','number'));
if(numeric)content+=panel('数值设置',(f.type!=='rating'?input('单位','unit',f.unit||'')+input('小数位数','decimals',f.decimals??'','min="0" max="6" placeholder="留空不限"','number'):'')+input('最小值','min',f.min??0,'step="any"','number')+(f.type==='rating'?select('评分制','max',[[5,'5 分制'],[10,'10 分制']],f.max||5):input('最大值','max',f.max??'','step="any" placeholder="留空不限"','number'))+(['money','formula'].includes(f.type)?setting('显示金额大写','uppercase',f.uppercase!==false):''));
if(f.type==='money')content+=select('金额计算方式','totalFrom',[['','手动填写'],...draft().fields.filter(x=>x.type==='table'&&(!x.columns||['quantity','price'].every(id=>x.columns.some(c=>c.id===id)))).map(x=>[x.id,'合计：'+x.label])],f.totalFrom||'');
if(f.type==='formula')content+=panel('计算公式',textarea('四则运算表达式','expression',f.expression||'','placeholder="例如：{数量字段ID} * {单价字段ID}"')+`<div class="oa-ref-list">${draft().fields.filter(x=>x.id!==f.id&&['number','money','formula'].includes(x.type)).map(x=>btn(esc(x.label),'oa-insert-ref',`data-id="${esc(x.id)}"`,'compact')).join('')}</div><p class="ga-helper">点击字段插入引用，支持 + − * / 和括号。计算结果只读。</p>`);
if(['date','daterange'].includes(f.type))content+=select('日期类型','dateFormat',[['date','年-月-日'],['datetime-local','年-月-日 时:分'],['month','年-月']],f.dateFormat||'date');
if(f.type==='daterange')content+=input('开始标题','startLabel',f.startLabel||'开始时间')+input('结束标题','endLabel',f.endLabel||'结束时间')+setting('自动计算时长','duration',f.duration!==false);
if(f.type==='description')content+=textarea('说明内容','content',f.content||'','rows="5"')+input('跳转链接','url',f.url||'','placeholder="https://"')+setting('不在审批详情显示','hideOnDetail',f.hideOnDetail);
if(f.type==='phone')content+=select('号码类型','phoneType',[['mobile','仅手机'],['both','手机和固话'],['landline','仅固话']],f.phoneType||'mobile');
if(f.type==='idcard')content+='<p class="callout">自动校验 18 位身份证号码、出生日期和校验位。</p>';
if(['image','attachment'].includes(f.type))content+=input('上传数量上限','maxCount',f.maxCount||9,'min="1" max="50"','number')+(f.type==='attachment'?input('允许的文件后缀','accept',f.accept||'','placeholder="例如：.pdf,.docx,.xlsx；留空不限"'):'')+'<p class="ga-helper">原型附件单个 1 MB，总计 3 MB。图片支持 JPG、PNG、GIF、WebP。</p>';
if(['person','department','related'].includes(f.type))content+=setting('允许多选','multiple',f.multiple)+(f.type==='person'?panel('人员选择范围（不选则全部）',options(C.people(),f.scope||[],'scopePeople')):'');
if(f.type==='related')content+=select('限定关联表单','templateId',[['','全部审批表单'],...state().templates.map(t=>[t.id,t.draft.basic.name])],f.templateId||'');
if(f.type==='department')content+=setting('展示部门全部层级','fullPath',f.fullPath);
if(f.type==='region')content+=select('格式','regionFormat',[['city','省 / 市'],['district','省 / 市 / 区'],['street','省 / 市 / 区 / 街道']],f.regionFormat||'district');
if(f.type==='location')content+='<p class="ga-helper">填写详细地址。当前原型不读取设备定位。</p>';
if(f.type==='signature')content+=select('签名方式','signatureMode',[['fresh','每次重新签名']],f.signatureMode||'fresh');
if(f.type==='serial')content+=panel('编号规则',input('固定前缀','prefix',f.prefix||'','maxlength="16"')+select('提交日期','serialDate',[['day','年月日'],['month','年月'],['year','年'],['none','不包含日期']],f.serialDate||'day')+input('自增位数','serialDigits',f.serialDigits||6,'min="1" max="8"','number')+select('重置周期','serialReset',[['year','按年'],['month','按月'],['day','按日'],['never','不重置']],f.serialReset||'year')+'<p class="ga-helper">正式提交时生成，退回重提保留原编号。本地存储范围内递增。</p>');
if(f.type==='table')content+=panel('明细设置',input('添加按钮名称','addLabel',f.addLabel||'添加明细','maxlength="20"')+textarea('明细列','columns',(f.columns||F.newField('table','').columns).map(c=>[c.label,c.type,c.required?'必填':'选填'].join(' | ')).join('\n'),'rows="6"')+'<p class="ga-helper">每行一列：标题 | text / number / money | 必填 / 选填。</p>'+input('最少行数','minRows',f.minRows??1,'min="0"','number')+input('最多行数','maxRows',f.maxRows||100,'min="1" max="500"','number')+select('展示方式','tableStyle',[['table','表格'],['list','列表']],f.tableStyle||'table')+select('打印方向','printOrientation',[['landscape','横向'],['portrait','纵向']],f.printOrientation||'landscape'));
content+=panel('通用设置',(f.type!=='description'?setting('必填','required',f.required):'')+setting('参与打印','print',f.print!==false)+(['phone','idcard','region','location'].includes(f.type)?setting('隐藏敏感信息','mask',f.mask):'')+select('显示条件','conditionField',[['','始终显示'],...draft().fields.filter(x=>x.id!==f.id&&!x.showWhen?.field&&['select','multiselect','text'].includes(x.type)).map(x=>[x.id,x.label+' 等于'])],f.showWhen?.field||'')+input('条件值','conditionValue',f.showWhen?.value||''));
return `<header><strong>字段属性</strong><span class="oa-property-kind"><span class="oa-control-icon">${controlIcon(f.type)}</span>${F.TYPES[f.type]}</span></header><form id="oa-field-properties">${content}<p class="oa-id">字段 ID：${esc(f.id)}</p></form>`;}
function controlIcon(type){
if(type==='text')return 'Aa';if(type==='number')return '123';if(type==='money')return '¥';if(type==='formula')return 'ƒ';
const paths={textarea:'M4 5h16M4 10h16M4 15h16M4 20h10',select:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',multiselect:'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2M7 12l3 3 7-7',date:'M3 7h18v14H3zM7 3v7M17 3v7M3 12h18M7 16h3',daterange:'M3 7h18v14H3zM7 3v7M17 3v7M3 12h18M7 16h10',description:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 10v7M12 7v.1',idcard:'M3 5h18v14H3zM10 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0M5 16c0-3 6-3 6 0M14 9h4M14 13h4',phone:'M7 3h10v18H7zM10 18h4',cascade:'M3 3h7v6H3zM14 15h7v6h-7zM6 9v9h8M14 3h7v6h-7zM10 6h4',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M17 7h.1',table:'M3 3h18v18H3zM3 9h18M3 15h18M9 3v18M15 3v18',attachment:'M8 12l7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3M7 14l8-8a2 2 0 0 1 3 3l-8 8',signature:'M3 21h18M5 15L17 3l4 4L9 19H5zM14 6l4 4',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',department:'M9 3h6v5H9zM3 16h6v5H3zM15 16h6v5h-6zM12 8v4M6 16v-4h12v4',location:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',related:'M10 14l4-4M8 16l-2 2a4 4 0 0 1-6-6l6-6a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-6 6a4 4 0 0 1-6 0',region:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16',rating:'M12 3l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',serial:'M9 3L7 21M17 3l-2 18M3 8h18M2 16h18'};
return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[type]||paths.description}"/></svg>`;
}
function mock(f){
 const label=esc(f.label+'预览'),placeholder=esc(f.totalFrom?'自动合计':f.type==='formula'?'自动计算数值':f.type==='serial'?'提交时自动生成编号':f.placeholder||'请输入');
 let body='';
 if(f.type==='description')body=`<p class="oa-description">${esc(f.content||'请输入说明文字')}</p>`;
 else if(f.type==='table')body=`<div class="oa-mock-table">${(f.columns||F.newField('table','').columns).map(c=>`<span>${esc(c.label)}</span>`).join('')}</div><p class="ga-helper">＋ ${esc(f.addLabel||'添加明细')}</p>`;
 else if(['attachment','image','signature'].includes(f.type))body=btn(f.type==='signature'?'手写签名':'＋ 上传'+F.TYPES[f.type],'','disabled');
 else if(f.type==='rating')body=`<span class="oa-stars">${'☆'.repeat(Number(f.max||5))}</span>`;
 else if(f.type==='daterange')body=`<div class="oa-mock-range"><input type="${f.dateFormat||'date'}" disabled aria-label="${label}开始"><span>至</span><input type="${f.dateFormat||'date'}" disabled aria-label="${label}结束"></div>`;
 else if(['select','multiselect'].includes(f.type)&&f.inline)body=`<div class="oa-input-options inline">${f.options.map(value=>`<label><input type="${f.type==='select'?'radio':'checkbox'}" disabled>${esc(value)}</label>`).join('')}</div>`;
 else if(['select','multiselect','person','department','related','cascade'].includes(f.type))body=`<select disabled aria-label="${label}"><option>${esc(f.defaultValue||f.placeholder||'请选择')}</option></select>`;
 else if(f.type==='textarea')body=`<textarea disabled rows="2" aria-label="${label}" placeholder="${placeholder}">${esc(f.defaultValue||'')}</textarea>`;
 else body=`<input type="${f.type==='date'?f.dateFormat||'date':'text'}" disabled aria-label="${label}" value="${esc(f.defaultValue??'')}" placeholder="${placeholder}">${f.unit?`<small>${esc(f.unit)}</small>`:''}`;
 return `<div class="oa-mock-control" aria-hidden="true">${body}</div>`;
}
let canvasPosition=null;
const priorAfterRender=A.afterRender;
A.afterRender=()=>{
 priorAfterRender?.();
 const position=canvasPosition;canvasPosition=null;
 if(!position)return;
 requestAnimationFrame(()=>{
  const canvas=document.querySelector('.oa-canvas'),card=document.querySelector('.oa-field.selected');
  if(!canvas)return;
  canvas.scrollTop=position.canvas;
  const palette=document.querySelector('.oa-palette'),properties=document.querySelector('.oa-properties');
  if(palette)palette.scrollTop=position.palette;
  if(properties)properties.scrollTop=position.changed?0:position.properties;
  if(position.changed&&card){const area=canvas.getBoundingClientRect(),field=card.getBoundingClientRect();if(field.bottom>area.bottom)canvas.scrollTop+=field.bottom-area.bottom+12;if(field.top<area.top)canvas.scrollTop+=field.top-area.top-12;}
  if(position.keyboard&&card)card.focus({preventScroll:true});
 });
};
O.formView=d=>{
 const previous=owner===C.editor&&document.querySelector('.oa-designer');
 canvasPosition=previous?{canvas:previous.querySelector('.oa-canvas').scrollTop,palette:previous.querySelector('.oa-palette').scrollTop,properties:previous.querySelector('.oa-properties').scrollTop,changed:previous.querySelector('.oa-field.selected')?.dataset.id!==selected,keyboard:document.activeElement?.matches('.oa-field')}:null;
 sync();
 return `<div class="oa-designer">
  <aside class="oa-palette" aria-label="表单控件库">
   <header><strong>控件库</strong><span class="muted small">点击或拖入表单</span></header>
   ${F.GROUPS.map(([name,types])=>`<section><h4>${name}</h4><div class="oa-palette-grid">${types.map(type=>`<button type="button" draggable="true" data-drag-type="${type}" data-action="field-new" data-type="${type}" style="width:100%;justify-content:flex-start"><span class="oa-palette-item"><span class="oa-control-icon">${controlIcon(type)}</span><span>${F.TYPES[type]}</span></span></button>`).join('')}</div></section>`).join('')}
   <details class="oa-integrations"><summary>业务与集成控件</summary><div class="oa-palette-grid">${['AI控件','外部联系人','行业通讯录部门','发票','客户','收款账户','预算申请','关联合同','工程项目','通用文字识别','身份证识别'].map(name=>btn(esc(name),'oa-integration',`data-name="${esc(name)}" style="width:100%;justify-content:flex-start"`)).join('')}</div><p class="ga-helper">连接业务数据源或服务后使用。</p></details>
  </aside>
  <main class="oa-design-stage" aria-label="表单画布">
   <div class="oa-design-toolbar"><div class="actions" aria-label="预览设备">${btn('手机','oa-device',`data-device="phone" aria-pressed="${device==='phone'}"`,device==='phone'?'primary':'')}${btn('电脑','oa-device',`data-device="desktop" aria-pressed="${device==='desktop'}"`,device==='desktop'?'primary':'')}</div><div class="actions">${btn('撤销','oa-undo',past.length?'':'disabled')}${btn('重做','oa-redo',future.length?'':'disabled')}${btn('填写预览','oa-preview')}</div></div>
   <div class="oa-canvas"><div class="oa-device ${device}"><div class="oa-form-caption"><strong>${esc(d.basic.name)}</strong><small>${esc(d.basic.description||'审批申请表')}</small></div><form id="oa-canvas-form" novalidate><div class="oa-drop-zone" data-drop-zone>
    ${d.fields.map((f,i)=>`<section class="ga-field-card oa-field ${selected===f.id?'selected':''}" draggable="true" data-drag-field="${esc(f.id)}" data-action="oa-select" data-id="${esc(f.id)}" tabindex="0" role="group" aria-label="${esc(f.label)}字段">
     <div class="oa-field-label"><span class="oa-field-title">${f.required?'<span class="ga-required">*</span>':''}<span>${esc(f.label)}</span></span><div class="oa-field-tools">
      ${btn('↑','field-move',`data-index="${i}" data-delta="-1" ${i===0?'disabled':''} aria-label="上移${esc(f.label)}" title="上移"`,'quiet compact')}${btn('↓','field-move',`data-index="${i}" data-delta="1" ${i===d.fields.length-1?'disabled':''} aria-label="下移${esc(f.label)}" title="下移"`,'quiet compact')}${btn('复制','oa-copy-field',`data-id="${esc(f.id)}" aria-label="复制字段"`,'quiet compact')}${btn('删除','field-delete',`data-id="${esc(f.id)}" aria-label="删除字段"`,'quiet compact')}
     </div></div><div class="oa-mock-body">${mock(f)}${f.help?`<small>${esc(f.help)}</small>`:''}${f.showWhen?.field?'<span class="oa-conditional">条件显示</span>':''}</div>
    </section>`).join('')}<div class="oa-drop-hint">＋ 添加控件</div>
   </div></form></div></div>
   <div class="oa-stage-footer"><span>${d.fields.length} 个控件</span><span>保存草稿后发布生效</span></div>
  </main>
  <aside class="oa-properties" aria-label="字段属性">${propertyView(field())}</aside>
 </div>`;
};
A.actions['field-new']=b=>{C.capture();history();const f=F.newField(b.dataset.type,E.id('field'));draft().fields.push(f);selected=f.id;C.changed();A.render();};
A.actions['oa-select']=b=>{captureField();selected=b.dataset.id;A.render();};
document.addEventListener('keydown',event=>{if(!PCGroupUI.owns(event.target))return;const card=event.target.closest('.oa-field[data-id]');if(card&&event.target===card&&['Enter',' '].includes(event.key)){event.preventDefault();A.actions['oa-select'](card);}});A.actions['field-edit']=A.actions['oa-select'];
A.actions['oa-copy-field']=b=>{C.capture();history();const f=E.clone(draft().fields.find(f=>f.id===b.dataset.id));f.id=E.id('field');f.label+='（副本）';draft().fields.push(f);selected=f.id;C.changed();A.render();};
A.actions['oa-device']=b=>{C.capture();device=b.dataset.device;A.render();};
A.actions['oa-undo']=()=>{if(!past.length)return;future.push(E.clone(draft().fields));draft().fields=past.pop();selected=draft().fields[0]?.id;C.changed();A.render();};
A.actions['oa-redo']=()=>{if(!future.length)return;past.push(E.clone(draft().fields));draft().fields=future.pop();selected=draft().fields[0]?.id;C.changed();A.render();};
A.actions['oa-insert-ref']=b=>{const el=document.querySelector('[name=expression]');el.value+='{'+b.dataset.id+'}';el.dispatchEvent(new Event('input',{bubbles:true}));captureField();C.changed();};
A.actions['oa-integration']=b=>A.open(b.dataset.name+' · 接入说明',`<p class="detail-text">${esc(b.dataset.name)}需要连接相应业务系统${/AI|识别/.test(b.dataset.name)?'或识别服务':''}。当前集团审批为本地原型，尚未接入。</p><p class="ga-helper mt">可先使用联系人、部门、附件、金额或关联审批单采集相关信息。接入后再配置数据范围、回写规则与授权。</p>`);
A.actions['flow-initiator']=()=>A.actions['rule-tab']({dataset:{tab:'basic'}});
const oldMove=A.actions['field-move'];A.actions['field-move']=b=>{C.capture();history();oldMove(b);};
let dragged=null;document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-type],[data-drag-field]');if(el){dragged={type:el.dataset.dragType,id:el.dataset.dragField};e.dataTransfer.effectAllowed='copyMove';e.dataTransfer.setData('text/plain',dragged.id||dragged.type);}});document.addEventListener('dragover',e=>{if(dragged&&e.target.closest('[data-drop-zone]'))e.preventDefault();});document.addEventListener('drop',e=>{if(!dragged||!e.target.closest('[data-drop-zone]'))return;e.preventDefault();const target=e.target.closest('[data-drag-field]')?.dataset.dragField;if(target&&dragged.id===target){dragged=null;return;}C.capture();history();const d=draft();let item;if(dragged.type)item=F.newField(dragged.type,E.id('field'));else item=d.fields.splice(d.fields.findIndex(x=>x.id===dragged.id),1)[0];const pos=target?d.fields.findIndex(x=>x.id===target):-1;d.fields.splice(pos<0?d.fields.length:pos,0,item);selected=item.id;dragged=null;C.changed();A.render();});document.addEventListener('dragend',()=>dragged=null);
// Configuration layouts follow the OA reference while using the local approval engine.
const hint=text=>`<p class="oa-config-hint">${text}</p>`;
const configRow=(label,body)=>`<div class="oa-config-row"><div class="oa-config-label">${label}</div><div class="oa-config-value">${body}</div></div>`;
const configSection=(title,body)=>`<section class="oa-config-section"><h3>${title}</h3><div class="oa-config-grid">${body}</div></section>`;
const radios=(name,rows,value,extra='',stack=false)=>`<div class="oa-radio-group ${stack?'vertical':''}">${rows.map(([id,label,description])=>`<label><input type="radio" name="${esc(name)}" value="${esc(id)}" ${String(id)===String(value)?'checked':''} ${extra}><span>${esc(label)}${description?`<small>${esc(description)}</small>`:''}</span></label>`).join('')}</div>`;
const sc=(label,name,value)=>check(label,name,value).replace('<input ','<input data-setting ');
const si=(label,name,value,extra='',type='text')=>input(label,name,value,extra+' data-setting',type);
const sr=(name,rows,value,stack=false)=>radios(name,rows,value,'data-setting',stack);
const ni=(label,name,value,extra='',type='text')=>input(label,name,value,extra+' data-node',type);
const ns=(label,name,rows,value)=>select(label,name,rows,value).replace('<select ','<select data-node ');
const nc=(label,name,value)=>check(label,name,value).replace('<input ','<input data-node ');
const nr=(name,rows,value,stack=false)=>radios(name,rows,value,'data-node',stack);
const orderedSelection=(before,after)=>[...(before||[]).filter(x=>after.includes(x)),...after.filter(x=>!(before||[]).includes(x))];
function memberPicker(name,values=[],rows=C.people()){
 const selected=rows.filter(([id])=>values.includes(id));
 return `<details class="oa-member-picker" data-member-picker="${esc(name)}"><summary><span data-picker-count>${selected.length?'已选择 '+selected.length+' 名成员':'请选择成员'}</span><span class="blue">＋ 选择成员</span></summary><div class="oa-member-options"><input type="search" data-member-search placeholder="搜索姓名或岗位" aria-label="搜索成员"><div class="oa-picker-shortcuts">${btn('全部成员','oa-members-quick','data-kind="all"','quiet compact blue')}${btn('审批管理员','oa-members-quick','data-kind="admins"','quiet compact blue')}${btn('清空','oa-members-quick','data-kind="clear"','quiet compact')}</div>${options(rows,values,name)}</div></details><div class="oa-member-chips" data-member-chips="${esc(name)}">${values.map(id=>`<span>${esc(A.personName(id))}</span>`).join('')}</div>`;
}
function updateMemberPicker(root){
 const details=root.closest('[data-member-picker]');if(!details)return;
 const selected=[...details.querySelectorAll('input[type=checkbox][name]:not([name^="_pc-"]):checked')];
 details.querySelector('[data-picker-count]').textContent=selected.length?'已选择 '+selected.length+' 名成员':'请选择成员';
 details.nextElementSibling.innerHTML=selected.map(el=>`<span>${esc(A.personName(el.value))}</span>`).join('');
}
A.actions['oa-members-quick']=b=>{
 const box=(b.closest?b:document.querySelector('[data-member-picker] [data-kind="'+b.dataset.kind+'"]')).closest('[data-member-picker]');
 box.querySelectorAll('input[type=checkbox][name]:not([name^="_pc-"])').forEach(el=>{el.checked=b.dataset.kind==='all'||b.dataset.kind==='admins'&&E.admin(state(),el.value);PCUI.syncControl(el);});
 updateMemberPicker(box);
 if(box.closest('#oa-settings')){captureAdvanced(draft());C.changed();}else readNode();
};
function processSettings(s){
 return configSection('发起人设置',
  configRow('撤回设置',sc('允许发起人撤回审批中的申请','allowWithdraw',s.allowWithdraw!==false)+`<div class="oa-inline-config">${si('可撤回期限','withdrawDays',s.withdrawDays??0,'min="0" max="180" '+(s.allowWithdraw===false?'disabled':''),'number')}<span>天</span><small>0 表示不限</small></div>`)+
  configRow('催办设置',sc('允许发起人催办当前处理人','allowUrge',s.allowUrge!==false)))+
 configSection('审批人设置',
  configRow('审批人去重',sr('repeat',[['keep','每个节点均需审批'],['skip','同一审批人在流程中多次出现时，后续节点自动跳过']],s.repeat||'keep',true))+
  configRow('发起人自审',sr('self',[['delegate','交指定代审人处理'],['skip','审批人与发起人相同时，自动跳过本人']],s.self||'delegate',true)+`<div class="oa-inline-config" ${s.self==='skip'?'hidden':''}>${select('指定代审人','delegate',[['','请选择'],...C.people()],s.delegate).replace('<select ','<select data-setting ')}</div>`)+
  configRow('审批意见',sc('必须填写意见，才可以提交审批','opinionRequired',s.opinionRequired)+`<div ${s.opinionRequired?'':'hidden'}>${si('填写提示','opinionHint',s.opinionHint||'请填写审批意见','maxlength="200"')}</div>`+hint('节点也可单独设置意见必填。拒绝、退回和转交始终需要说明原因。'))+
  configRow('允许加签',sc('审批过程中，允许当前审批人新增临时审批人','allowAddSign',s.allowAddSign)+hint('加签后，当前节点所有未处理人员均同意才可通过。'))+
  configRow('转交审批',sc('允许当前处理人转交待办','allowTransfer',s.allowTransfer!==false))+
  configRow('退回审批',sc('允许退回发起人修改','allowReturn',s.allowReturn!==false)+hint('退回后再次提交：按本次冻结版本重新开始审批。'))+
  configRow('消息通知设置',`<h4>当审批单被拒绝时，通知以下人员</h4>${sc('拒绝节点前，已经参与处理的人员','notifyRejectedPrevious',s.notifyRejectedPrevious)}${sc('当前节点的其他审批人','notifyRejectedPeers',s.notifyRejectedPeers)}<h4>当或签节点被同意时</h4>${sc('通知该节点的其他审批人','notifyApprovedPeers',s.notifyApprovedPeers)}${hint('发起人始终收到拒绝和办结通知；以上选项控制额外的站内通知。')}`));
}
const summaryFields=d=>d.fields.filter(f=>!['table','description','signature','image','attachment'].includes(f.type));
function summaryPreview(d){
 const s=d.settings,picked=(s.summaryMode==='custom'||!s.summaryMode&&s.summaryFields?.length)?(s.summaryFields||[]).map(id=>d.fields.find(f=>f.id===id)).filter(Boolean):[...summaryFields(d)].sort((a,b)=>Number(!!b.required)-Number(!!a.required)).slice(0,5);
 const sampleTitle=s.titleMode==='auto'?(s.titlePattern||'{发起人}的{表单名称}').replace(/\{([^{}]+)\}/g,(_,key)=>({'发起人':'张三','表单名称':d.basic.name,'公司':'集团总部'}[key]||d.fields.find(f=>f.id===key)?.label||key)):d.basic.name;
 return `<div class="oa-summary-preview"><div class="oa-preview-icon">${A.icon('list')}</div><div><strong data-title-sample>${esc(sampleTitle)}</strong>${picked.map(f=>`<p>${esc(f.label)}<span>${esc(f.defaultValue||'示例内容')}</span></p>`).join('')||hint('选择摘要字段后显示预览')}<small>展示示例 · 实际内容按申请及字段查看权限显示</small></div></div>`;
}
function summarySettings(d){const s=d.settings,custom=s.summaryMode==='custom'||!s.summaryMode&&s.summaryFields?.length;
 return `<div class="oa-settings-intro"><h3>数据标题 / 摘要</h3>${hint('设置申请列表中的标题和摘要，方便快速识别审批内容。')}</div><section class="oa-config-section"><h3>标题设置</h3>${sr('titleMode',[['manual','由发起人填写'],['auto','按模板自动生成']],s.titleMode||'manual')}<div class="oa-title-template" ${s.titleMode==='auto'?'':'hidden'}>${si('标题模板','titlePattern',s.titlePattern||'{发起人}的{表单名称}','maxlength="80" placeholder="选择下方字段组合标题"')}<div class="oa-token-buttons"><span>插入字段</span>${[['发起人','发起人'],['表单名称','表单名称'],['公司','公司'],...summaryFields(d).map(f=>[f.id,f.label])].map(([id,label])=>btn(esc(label),'oa-title-token',`data-id="${esc(id)}"`,'compact')).join('')}</div>${hint('可组合固定文字和字段。例如：{发起人}的{表单名称}。')}</div></section><section class="oa-config-section"><h3>摘要设置</h3>${sr('summaryMode',[['default','默认'],['custom','自定义模式']],custom?'custom':'default')}<div class="oa-summary-rule"><span>${custom?(s.summaryFields||[]).map(id=>esc(d.fields.find(f=>f.id===id)?.label||id)).join('、')||'尚未选择摘要字段':'展示前 5 个字段，必填字段优先'}</span>${btn('编辑摘要','oa-summary-edit','','compact')}</div>${hint('自定义摘要最多选择 5 个字段，支持调整显示顺序。')}</section><section class="oa-config-section"><h3>显示预览</h3>${summaryPreview(d)}</section>`;
}
function permissionSettings(s){
 const card=g=>`<section class="oa-permission-card" data-permission="${esc(g.id)}"><header>${input('权限组名称','permissionName:'+g.id,g.name,'maxlength="30"')}${btn('删除权限组','oa-permission-remove',`data-id="${esc(g.id)}"`,'quiet compact red')}</header><div class="oa-permission-row"><span>权限成员</span><div>${memberPicker('permissionMembers:'+g.id,g.members)}</div></div><div class="oa-permission-row"><span>管理范围</span>${radios('permissionScope:'+g.id,[['own','本人发起或参与'],['company','所属公司'],['department','所在部门'],['group','集团全部公司']],g.scope)}</div><div class="oa-permission-row"><span>操作权限</span><div class="oa-operation-checks">${check('查看','permissionView:'+g.id,g.view)}${check('导出','permissionExport:'+g.id,g.export)}</div></div></section>`;
 return `<input type="hidden" name="permissionMarker" value="1"><div class="oa-settings-intro"><h3>权限管理</h3>${hint('设置审批数据的查看和导出权限。审批操作仍由流程节点决定。')}</div><section class="oa-permission-card default"><header><strong>默认权限组</strong><span class="pill">系统权限</span></header><div class="oa-permission-row"><span>权限成员</span><div class="oa-member-chips"><span>全部集团审批管理员</span></div></div><div class="oa-permission-row"><span>管理范围</span><span>集团全部公司</span></div><div class="oa-permission-row"><span>操作权限</span><span>查看、导出与审批配置管理</span></div></section>${(s.permissions||[]).map(card).join('')}${btn('＋ 新增权限组（'+(s.permissions?.length||0)+'/10）','oa-permission-add',(s.permissions?.length||0)>=10?'disabled':'','blue compact')}<section class="oa-config-section"><h3>权限组外人员查看权限</h3>${sr('outsideView',[['participants','仅流程参与人和所属公司管理员'],['company','申请所属公司的全部成员']],s.outsideView||'participants',true)}${hint('额外权限随发布版本生效；历史申请保留提交时的数据权限。')}</section>`;
}
O.settingsView=d=>`<div class="oa-advanced"><nav aria-label="高级设置分类" aria-orientation="vertical">${[['process','高级流程设置'],['summary','数据标题 / 摘要'],['permissions','权限管理']].map(([id,label])=>btn(label,'oa-advanced-tab',`id="oa-settings-tab-${id}" data-tab="${id}" aria-controls="oa-settings-panel" ${advancedTab===id?'aria-current="page"':''}`,advancedTab===id?'active':'')).join('')}</nav><section class="oa-settings-content" id="oa-settings-panel" role="tabpanel" aria-labelledby="oa-settings-tab-${advancedTab}"><form id="oa-settings" class="oa-settings-form">${advancedTab==='process'?processSettings(d.settings):advancedTab==='summary'?summarySettings(d):permissionSettings(d.settings)}</form></section></div>`;
A.actions['oa-advanced-tab']=b=>{C.capture();advancedTab=['process','summary','permissions'].includes(b.dataset.tab)?b.dataset.tab:'process';A.render();};
A.actions['oa-permission-add']=()=>{C.capture();const s=draft().settings;s.permissions=s.permissions||[];E.assert(s.permissions.length<10,'最多 10 个权限组');s.permissions.push({id:E.id('permission'),name:'权限组 '+(s.permissions.length+1),members:[],scope:'own',view:true,export:false});C.changed();A.render();};
A.actions['oa-permission-remove']=b=>{C.capture();draft().settings.permissions=draft().settings.permissions.filter(x=>x.id!==b.dataset.id);C.changed();A.render();};
A.actions['oa-title-token']=b=>{const el=document.querySelector('[name=titlePattern]'),start=el.selectionStart??el.value.length,end=el.selectionEnd??start;el.value=el.value.slice(0,start)+'{'+b.dataset.id+'}'+el.value.slice(end);el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();el.setSelectionRange(start+b.dataset.id.length+2,start+b.dataset.id.length+2);captureAdvanced(draft());C.changed();refreshTitleSample();};
function refreshTitleSample(){const preview=document.querySelector('.oa-summary-preview');if(preview)preview.outerHTML=summaryPreview(draft());}
let summaryDraft=[];
function drawSummaryPicker(){
 const fields=summaryFields(draft());
 A.open('摘要设置',`<div class="oa-summary-picker"><section><header><strong>审批单字段</strong><span>最多选择 5 个</span></header><div class="oa-summary-fields">${fields.map(f=>`<label><input type="checkbox" name="summaryFields" value="${esc(f.id)}" ${summaryDraft.includes(f.id)?'checked':''} ${summaryDraft.length>=5&&!summaryDraft.includes(f.id)?'disabled':''}>${esc(f.label)}${f.required?'<small>必填</small>':''}</label>`).join('')}</div></section><section><header><strong>摘要显示字段</strong><span>${summaryDraft.length}/5</span></header>${summaryDraft.map((id,i)=>`<div class="oa-summary-order"><span>${esc(fields.find(f=>f.id===id)?.label||id)}</span>${btn('↑','oa-summary-move',`data-index="${i}" data-delta="-1" ${i===0?'disabled':''} aria-label="上移摘要字段"`,'quiet compact')}${btn('↓','oa-summary-move',`data-index="${i}" data-delta="1" ${i===summaryDraft.length-1?'disabled':''} aria-label="下移摘要字段"`,'quiet compact')}${btn('×','oa-summary-remove',`data-id="${esc(id)}" aria-label="移除摘要字段"`,'quiet compact')}</div>`).join('')||hint('从左侧选择需要展示的字段')}</section></div>`,async()=>{E.assert(summaryDraft.length>0,'请至少选择一个摘要字段');draft().settings.summaryFields=[...summaryDraft];draft().settings.summaryMode='custom';C.changed();A.close();A.render();},{saveText:'确定',wide:true});
 document.querySelector('#ga-modal').classList.add('oa-summary-drawer');
}
A.actions['oa-summary-edit']=()=>{C.capture();summaryDraft=(draft().settings.summaryFields||[]).filter(id=>summaryFields(draft()).some(f=>f.id===id));drawSummaryPicker();};
A.actions['oa-summary-move']=b=>{const i=Number(b.dataset.index),j=i+Number(b.dataset.delta);[summaryDraft[i],summaryDraft[j]]=[summaryDraft[j],summaryDraft[i]];drawSummaryPicker();};
A.actions['oa-summary-remove']=b=>{summaryDraft=summaryDraft.filter(id=>id!==b.dataset.id);drawSummaryPicker();};
function readNode(){
 const form=document.querySelector('#modal-form');if(!form||!nodeEdit||!form.querySelector('[data-node-editor]'))return;
 const fd=new FormData(form);
 for(const el of form.querySelectorAll('input[data-node],select[data-node],textarea[data-node]')){if(el.type==='radio'&&!el.checked)continue;nodeEdit[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;}
 if(fd.has('peopleMarker'))nodeEdit.people=orderedSelection(nodeEdit.people,fd.getAll('people'));
 if(fd.has('selectPeopleMarker'))nodeEdit.selectPeople=fd.getAll('selectPeople');
 if(fd.has('permissionsMarker')){nodeEdit.fieldPermissions={};for(const f of draft().fields)nodeEdit.fieldPermissions[f.id]=fd.get('permission:'+f.id)||'read';}
 if(fd.has('templatesMarker')){nodeEdit.opinionTemplatesByAction={};for(const kind of ['approve','reject'])nodeEdit.opinionTemplatesByAction[kind]=fd.getAll('template:'+kind).map(x=>String(x).trim()).filter(Boolean);}
 if(fd.has('timingMarker')){nodeEdit.timing=C.readTiming(fd,'node',E.T.node(nodeEdit));nodeEdit.hours=nodeEdit.timing.hours;}
}
function sourceConfig(n){
 if(n.source==='person')return `<input type="hidden" name="peopleMarker" value="1">${memberPicker('people',n.people)}${n.mode==='sequential'&&n.people?.length>1?`<div class="oa-person-order">${n.people.map((id,i)=>`<div><span>${i+1}. ${esc(A.personName(id))}</span>${btn('↑','oa-person-move',`data-index="${i}" data-delta="-1" ${i===0?'disabled':''}`,'quiet compact')}${btn('↓','oa-person-move',`data-index="${i}" data-delta="1" ${i===n.people.length-1?'disabled':''}`,'quiet compact')}</div>`).join('')}</div>`:''}`;
 if(n.source==='selfSelect')return nc('允许选择多名处理人','selectMultiple',n.selectMultiple!==false)+`<input type="hidden" name="selectPeopleMarker" value="1">${hint('限定发起人可选择的成员；不选则为全部有效成员。')}${memberPicker('selectPeople',n.selectPeople)}`;
 if(['department','continuous'].includes(n.source))return `<div class="oa-context-fields">${ns('起始部门','base',[['applicant','发起人本次任职部门'],['fixed','指定部门']],n.base)}${n.base==='fixed'?ns('指定部门','department',[['','请选择'],...C.departments()],n.department):''}${ns(n.source==='continuous'?'逐级审批终点':'主管层级','level',Array.from({length:10},(_,i)=>[i+1,'第 '+(i+1)+' 级部门主管']),n.level)}</div>${hint('本次任职部门计为第 1 级，沿集团组织逐级向上查找，可跨公司主体。')}`;
 if(n.source==='position')return `<div class="oa-context-fields">${ns('处理岗位 / 角色','position',[...new Set(state().positions.map(p=>p.name))].map(p=>[p,p]),n.position)}${ns('任职匹配范围','scope',[['company','申请所属公司'],['group','集团总部']],n.scope)}</div>${hint('匹配所选范围内该岗位的全部有效任职人员。')}`;
 if(['formPerson','formDepartment'].includes(n.source))return ns('表单字段','field',[['','请选择'],...draft().fields.filter(f=>f.type===(n.source==='formPerson'?'person':'department')).map(f=>[f.id,f.label])],n.field||'')+(n.source==='formDepartment'?ns('主管层级','level',Array.from({length:10},(_,i)=>[i+1,'第 '+(i+1)+' 级']),n.level||1):'')+hint('根据发起人填写的字段值确定处理人。');
 return hint(n.source==='applicant'?'由发起人本人处理，此节点不应用自审代审规则。':'根据组织与人员中配置的直属上级确定处理人。');
}
function nodePeople(n){
 const groups=[['常用处理人',['person','applicant','selfSelect','position']],['主管',['manager','department','continuous']],['表单字段',['formPerson','formDepartment']]];
 return `<section class="oa-node-section"><h3>请选择该节点的${n.type==='cc'?'抄送人':'处理人'}</h3><div class="oa-source-grid">${groups.map(([title,ids])=>`<section><h4>${title}</h4>${nr('source',ids.map(id=>[id,E.SOURCE[id]]),n.source,true)}</section>`).join('')}</div></section><section class="oa-node-section oa-source-detail"><h3>${esc(E.SOURCE[n.source])}</h3>${sourceConfig(n)}</section>${n.type!=='cc'?`<section class="oa-node-section"><h3>多人${n.type==='handling'?'办理':'审批'}时采用的方式</h3>${nr('mode',[['sequential','依次处理','按人员顺序逐一处理'],['all',n.type==='handling'?'全部办理':'会签',n.type==='handling'?'所有处理人完成办理后继续':'需要所有处理人同意才可通过'],['any',n.type==='handling'?'任一办理':'或签',n.type==='handling'?'任一人完成办理后继续，任一人拒绝即结束':'其中一人同意即可通过，任一人拒绝即结束']],n.mode||'all',true)}</section>`:''}<section class="oa-node-section"><h3>处理人为空时</h3>${nr('emptyPolicy',[['block','阻断提交，交管理员维护'],['admin','自动转交集团管理员'],['person','交指定承接人'],['approve',n.type==='cc'?'跳过此抄送节点':'自动通过'],...(n.type==='cc'?[]:[['reject','自动拒绝']])],n.emptyPolicy||(n.fallback?'person':'block'),true)}${n.emptyPolicy==='person'||!n.emptyPolicy&&n.fallback?`<div class="oa-empty-assignee">${ns('指定承接人','fallback',[['','请选择'],...C.people()],n.fallback||'')}</div>`:''}</section>`;
}
const canEditField=(n,f)=>n.type!=='cc'&&!['formula','serial','description','signature','image','attachment','table'].includes(f.type)&&!f.totalFrom;
function nodePermissions(n){
 return `<input type="hidden" name="permissionsMarker" value="1">${hint(n.type==='cc'?'抄送人可查看获授权的字段，不能编辑表单。':'点击表头可批量设置字段权限。不可编辑的字段将保留原权限。')}<div class="oa-permission-table-wrap"><table class="oa-permission-table"><thead><tr><th scope="col">表单字段</th>${[['edit','可编辑'],['read','只读'],['hidden','隐藏']].map(([id,l])=>`<th scope="col"><label><input type="radio" name="permissionAll" value="${id}" data-action="oa-permission-all" data-mode="${id}" ${draft().fields.every(f=>(n.fieldPermissions?.[f.id]||'read')===id)?'checked':''} ${id==='edit'&&n.type==='cc'?'disabled':''}>${l}</label></th>`).join('')}</tr></thead><tbody>${draft().fields.map(f=>`<tr><td>${f.required?'<span class="ga-required">*</span>':''}${esc(f.label)}<small>${esc(F.TYPES[f.type])}${!canEditField(n,f)?' · 不可编辑':''}</small></td>${['edit','read','hidden'].map(mode=>`<td><input type="radio" name="permission:${esc(f.id)}" value="${mode}" aria-label="${esc(f.label)}${{edit:'可编辑',read:'只读',hidden:'隐藏'}[mode]}" ${(n.fieldPermissions?.[f.id]||'read')===mode?'checked':''} ${mode==='edit'&&!canEditField(n,f)?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function nodeAdvanced(n){
 if(n.type==='cc')return `<section class="oa-node-section"><h3>抄送规则</h3>${configRow('发送时机','流程到达该节点时，自动发送站内抄送消息')}${configRow('表单权限','遵守“表单操作权限”中设置的只读或隐藏规则')}${configRow('办理要求','无需确认或审批，不设置办理时限')}</section><section class="oa-node-section"><h3>人员配置</h3>${hint(n.source==='selfSelect'?'当前由发起人选择抄送人，可在“设置处理人”中限定可选范围。':'当前按“'+esc(E.SOURCE[n.source])+'”自动匹配抄送人。')}</section>`;
 const templates=n.opinionTemplatesByAction||{approve:n.opinionTemplates||[],reject:[]},enabled=n.opinionTemplatesEnabled??Object.values(templates).some(a=>a.length);
 return `<section class="oa-node-section"><h3>操作权限</h3><div class="oa-node-operation-grid">${nc('允许转交','allowTransfer',n.allowTransfer!==false)}${nc('允许退回发起人','allowReturn',n.allowReturn!==false)}${nc(n.type==='handling'?'必须填写办理意见':'必须填写审批意见','opinionRequired',n.opinionRequired)}</div>${hint('同时受表单高级流程设置约束；全局禁止的操作不能在此开启。')}</section><section class="oa-node-section"><h3>${n.type==='handling'?'办理':'审批'}意见模板</h3><input type="hidden" name="templatesMarker" value="1">${setting('启用'+(n.type==='handling'?'办理':'审批')+'意见模板','opinionTemplatesEnabled',enabled,'处理申请时，可点击模板快速填写意见。').replace('<input ','<input data-node ')}<div data-template-options ${enabled?'':'hidden'}>${[['approve',n.type==='handling'?'完成办理':'审批同意'],['reject','审批拒绝']].map(([kind,label])=>`<div class="oa-template-card"><h4>${label}<small>最多 3 条，每条 25 字</small></h4>${Array.from({length:3},(_,i)=>`<label><span>${i+1}</span><input name="template:${kind}" value="${esc(templates[kind]?.[i]||'')}" maxlength="25" placeholder="请输入常用回复" aria-label="${label}模板 ${i+1}"></label>`).join('')}</div>`).join('')}</div></section><section class="oa-node-section"><h3>节点限时处理</h3><input type="hidden" name="timingMarker" value="1">${C.timingControls('node',E.T.node(n))}</section>`;
}
O.drawNode=(n,context)=>{
 if(nodeEdit!==n){nodeEdit=n;nodeCtx=context;nodeTab='people';}
 const automatic=n.type==='approval'&&n.approvalType&&n.approvalType!=='manual';
 const tabs=[['people','设置处理人'],['permissions','表单操作权限'],['advanced','高级设置']];
 const body=automatic?`<div class="oa-auto-node"><span>${A.icon(n.approvalType==='approve'?'check':'rule')}</span><h3>${n.approvalType==='approve'?'自动通过':'自动拒绝'}</h3>${hint(n.approvalType==='approve'?'流程到达后自动通过并进入下一节点，无需人工处理。':'流程到达后自动拒绝并结束申请，无需人工处理。')}${hint('系统会记录处理结果。切回人工审批可继续配置处理人。')}</div>`:nodeTab==='people'?nodePeople(n):nodeTab==='permissions'?nodePermissions(n):nodeAdvanced(n);
 A.open(n.type==='cc'?'设置抄送节点':n.type==='handling'?'设置办理节点':'设置审批节点',`<div class="oa-node-editor" data-node-editor><div class="oa-node-meta">${ni('节点名称','title',n.title,'maxlength="40"')}${n.type==='approval'?`<div class="oa-approval-type"><span>审批类型</span>${nr('approvalType',[['manual','人工审批'],['approve','自动通过'],['reject','自动拒绝']],n.approvalType||'manual')}</div>`:''}</div><nav class="oa-node-tabs" aria-label="节点配置">${tabs.map(([id,label])=>btn(label,'oa-node-tab',`data-tab="${id}" ${nodeTab===id?'aria-current="page"':''}`,nodeTab===id?'active':'')).join('')}</nav><div class="oa-node-body">${body}</div></div>`,async()=>{readNode();E.assert(n.title.trim(),'请填写节点名称');E.validateNode(state(),draft(),n);if(nodeCtx.id)Object.assign(C.findNode(nodeCtx.id),E.clone(n));else C.findList(nodeCtx.list).splice(nodeCtx.index,0,E.clone(n));C.changed();A.close();A.render();},{saveText:'确定',wide:true});
 document.querySelector('#ga-modal').classList.add('oa-node-drawer');
};
A.actions['oa-node-tab']=b=>{readNode();nodeTab=b.dataset.tab;O.drawNode(nodeEdit,nodeCtx);};
A.actions['oa-person-move']=b=>{readNode();const i=Number(b.dataset.index),j=i+Number(b.dataset.delta);[nodeEdit.people[i],nodeEdit.people[j]]=[nodeEdit.people[j],nodeEdit.people[i]];O.drawNode(nodeEdit,nodeCtx);};
function syncPermissionHeader(){const rows=[...document.querySelectorAll('.oa-permission-table input[type=radio][name^="permission:"]:checked')];document.querySelectorAll('[name=permissionAll]').forEach(el=>{el.checked=rows.length>0&&rows.every(row=>row.value===el.value);PCUI.syncControl(el);});}
A.actions['oa-permission-all']=b=>{document.querySelectorAll('#modal-form input[type=radio]').forEach(el=>{if(el.name.startsWith('permission:')&&el.value===b.dataset.mode&&!el.disabled)el.checked=true;});document.querySelectorAll('#modal-form input[type=radio]').forEach(el=>PCUI.syncControl(el));readNode();syncPermissionHeader();};

// Form management keeps the existing template lifecycle and optimistic revision checks.
A.views.rules=()=>{
 if(!E.admin(state(),A.actor))return A.deny();
 const groups=state().categories;
 let rows=state().templates.filter(t=>(!query||t.draft.basic.name.includes(query))&&(groupFilter==='disabled'?!!t.published&&!t.enabled:!groupFilter||t.draft.basic.category===groupFilter));
 if(groupFilter!=='disabled')rows=rows.filter(t=>!t.published||t.enabled);
 const tabs=[['','全部表单'],...groups.map(c=>[c.id,c.name]),['disabled','已停用']];
 const categories=groupFilter==='disabled'?[{id:'disabled',name:'已停用'}]:groups.filter(c=>!groupFilter||c.id===groupFilter);
 const sections=categories.map(c=>{
  const items=rows.filter(t=>c.id==='disabled'||t.draft.basic.category===c.id);
  if(!items.length&&query)return '';
  const used=state().templates.some(t=>t.draft.basic.category===c.id||t.published?.basic.category===c.id);
  return `<section class="oa-group"><header><h2>${esc(c.name)}<span class="muted">（${items.length}）</span></h2><div class="oa-group-actions">${btn('表单排序','oa-form-sort',`data-id="${c.id}" ${items.length<2?'disabled':''}`,'quiet compact')}${c.id!=='disabled'?btn('分组设置','category-edit',`data-id="${c.id}"`,'quiet compact')+btn('删除空分组','category-delete',`data-id="${c.id}" ${used?'disabled title="分组中仍有表单"':''}`,'quiet compact red'):''}</div></header><div class="table-wrap"><table class="ga-table"><colgroup>${batch?'<col class="oa-col-select">':''}<col class="oa-col-form"><col class="oa-col-scope"><col class="oa-col-updated"><col class="oa-col-actions"></colgroup><thead><tr>${batch?'<th scope="col">选择</th>':''}<th scope="col">表单</th><th scope="col">谁可以发起</th><th scope="col">最后更新 / 版本</th><th scope="col">操作</th></tr></thead><tbody>${items.map(t=>`<tr>${batch?`<td><input type="checkbox" data-batch-id="${t.id}" aria-label="选择${esc(t.draft.basic.name)}" ${chosen.has(t.id)?'checked':''} ${t.enabled?'':'disabled'}></td>`:''}<td><div class="oa-form-summary"><span class="oa-form-icon small">${A.icon('list')}</span><div><strong>${esc(t.draft.basic.name)}</strong><span class="ga-sub" title="${esc(t.draft.basic.description)}">${esc(t.draft.basic.description)}</span></div></div></td><td>${t.draft.basic.initiators?.length?'指定 '+t.draft.basic.initiators.length+' 名成员':t.draft.basic.companies.includes('*')?'集团全部成员':'指定 '+t.draft.basic.companies.length+' 个公司'}${t.draft.basic.departments?.length?'<span class="ga-sub">指定部门</span>':''}</td><td>${A.date(t.updatedAt)}<span class="ga-sub">${t.published?'V'+t.version:'未发布'}${t.dirty?' · 有待发布草稿':''}</span></td><td class="actions">${A.link('编辑','rule/'+t.id+'/basic')}${btn('导出','oa-export-form',`data-id="${t.id}"`,'quiet compact blue')}${btn('更多','oa-form-more',`data-id="${t.id}"`,'quiet compact blue')}</td></tr>`).join('')}</tbody></table></div>${!items.length?'<div class="oa-empty-group">暂无表单</div>':''}</section>`;
 }).join('');
 return `<div class="oa-management-page"><section class="panel rules-query-panel"><nav class="tabs oa-groups" aria-label="表单分类">${tabs.map(([id,label])=>`<button type="button" data-action="oa-group-filter" data-id="${esc(id)}" class="${groupFilter===id?'active':''}" ${groupFilter===id?'aria-current="page"':''}>${esc(label)}</button>`).join('')}</nav></section><section class="panel rules-query-panel"><form id="oa-form-search"><label for="oa-search-input">表单名称</label><input id="oa-search-input" type="search" name="q" value="${esc(query)}" placeholder="请输入表单名称"><button class="btn primary" type="submit">查询</button>${btn('重置','oa-search-reset')}</form></section>${contentModule('审批表单',`${batch?`<div class="oa-batch-bar"><span>已选择 ${chosen.size} 个表单</span></div>`:''}${sections||A.empty('暂无匹配表单','请调整搜索条件。')}`,`${btn('分组排序','oa-group-sort')}${btn(batch?'取消批量':'批量停用','oa-batch')}${batch?btn('停用所选','oa-batch-confirm',chosen.size?'':'disabled','danger'):''}${btn('＋ 新建分组','category-new')}${btn('＋ 创建审批表单','rule-new','','primary')}`,'oa-management')}</div>`;
};
A.actions['oa-search-reset']=()=>{query='';A.render();};
A.forms['oa-form-search']=f=>{query=String(new FormData(f).get('q')||'').trim();A.render();};A.actions['oa-group-filter']=b=>{groupFilter=b.dataset.id;chosen.clear();A.render();};A.actions['oa-batch']=()=>{batch=!batch;chosen.clear();A.render();};
A.actions['oa-batch-confirm']=()=>A.confirm('批量停用表单','停用所选 '+chosen.size+' 个表单后不再允许新申请；已提交申请继续处理。',async()=>{await A.mutate(s=>s.templates.filter(t=>chosen.has(t.id)).forEach(t=>{t.enabled=false;t.updatedAt=Date.now();t.editRevision=(t.editRevision||0)+1;}));chosen.clear();batch=false;},'确认停用');
A.actions['oa-form-more']=b=>{const t=state().templates.find(t=>t.id===b.dataset.id),data=`data-id="${t.id}"`;A.open(t.draft.basic.name+' · 更多操作',`<div class="oa-more-actions">${btn('复制表单','rule-copy',data)}${btn('移动到其他分组','oa-form-move',data)}${btn('模拟预览','rule-preview',data)}${t.published?btn(t.enabled?'停用表单':'启用表单','rule-toggle',data):btn('删除未发布草稿','rule-delete',data,'red')}</div>`);};
A.actions['oa-export-form']=b=>{const t=state().templates.find(t=>t.id===b.dataset.id);const data={format:'group-approval-form',exportedAt:new Date().toISOString(),name:t.draft.basic.name,version:t.version,draft:t.draft,published:t.published};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=t.draft.basic.name+'-表单配置.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);A.toast('表单与流程配置已导出');};
A.actions['oa-form-move']=b=>{const t=state().templates.find(t=>t.id===b.dataset.id);A.open('移动表单分组',select('目标分组','category',state().categories.map(c=>[c.id,c.name]),t.draft.basic.category),async f=>{const category=f.elements.category.value;await A.mutate(s=>{const x=s.templates.find(x=>x.id===t.id);x.draft.basic.category=category;x.dirty=true;x.editRevision=(x.editRevision||0)+1;x.updatedAt=Date.now();});A.close();A.render();},{saveText:'移动到此分组'});};
let sortDraft=[],sortType='',sortGroup='';function sortDialog(){A.open(sortType==='groups'?'分组排序':'表单排序',`<div class="oa-sort-list">${sortDraft.map((x,i)=>`<div><span>${esc(x.name||x.draft.basic.name)}</span>${btn('↑','oa-sort-move',`data-index="${i}" data-delta="-1" ${i===0?'disabled':''}`,'compact')}${btn('↓','oa-sort-move',`data-index="${i}" data-delta="1" ${i===sortDraft.length-1?'disabled':''}`,'compact')}</div>`).join('')}</div>`,async()=>{await A.mutate(s=>{if(sortType==='groups'){const ids=sortDraft.map(x=>x.id);s.categories.sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id));}else{const ids=sortDraft.map(x=>x.id),positions=s.templates.map((t,i)=>ids.includes(t.id)?i:-1).filter(i=>i>=0),items=ids.map(id=>s.templates.find(t=>t.id===id));positions.forEach((pos,i)=>s.templates[pos]=items[i]);}});A.close();A.render();});}A.actions['oa-group-sort']=()=>{sortType='groups';sortDraft=E.clone(state().categories);sortDialog();};A.actions['oa-form-sort']=b=>{sortType='forms';sortGroup=b.dataset.id;sortDraft=E.clone(state().templates.filter(t=>sortGroup==='disabled'?!t.enabled&&t.published:t.draft.basic.category===sortGroup));sortDialog();};A.actions['oa-sort-move']=b=>{const i=Number(b.dataset.index),j=i+Number(b.dataset.delta);[sortDraft[i],sortDraft[j]]=[sortDraft[j],sortDraft[i]];sortDialog();};
const prevInput=A.onInput,prevChange=A.onChange;A.onInput=e=>{prevInput?.(e);if(e.target.closest('#oa-field-properties,#oa-settings')){O.capture(draft());C.changed();if(e.target.closest('#oa-field-properties')){const card=document.querySelector('.oa-field.selected');if(card){const f=field();card.querySelector('.oa-field-title').innerHTML=(f.required?'<span class="ga-required">*</span>':'')+'<span>'+esc(f.label)+'</span>';let body=card.querySelector('.oa-mock-body');if(!body){body=document.createElement('div');body.className='oa-mock-body';const label=card.querySelector('.oa-field-label');while(label.nextSibling)body.appendChild(label.nextSibling);card.appendChild(body);}body.innerHTML=mock(f)+(f.help?'<small>'+esc(f.help)+'</small>':'');}}}};
A.onChange=e=>{prevChange?.(e);if(e.target.closest('#oa-field-properties,#oa-settings')){O.capture(draft());if(e.target.name==='scopePeople')field().scope=new FormData(e.target.form).getAll('scopePeople');C.changed();if(['inline','multiple','dateFormat','max','tableStyle'].includes(e.target.name))A.render();}if(e.target.closest('#rule-basic')){captureBasic(draft());C.changed();if(e.target.name==='initiatorMode')document.querySelector('[data-basic-members]').hidden=e.target.value!=='selected';if(e.target.name==='adminMode')document.querySelector('[data-basic-admins]').hidden=e.target.value!=='selected';}if(e.target.matches('[data-node]')){readNode();if(['source','base','approvalType','emptyPolicy','mode'].includes(e.target.name))O.drawNode(nodeEdit,nodeCtx);if(e.target.name==='opinionTemplatesEnabled')document.querySelector('[data-template-options]').hidden=!e.target.checked;}if(e.target.matches('[data-batch-id]')){e.target.checked?chosen.add(e.target.dataset.batchId):chosen.delete(e.target.dataset.batchId);A.render();}};
const layoutInput=A.onInput,layoutChange=A.onChange;
A.onInput=e=>{layoutInput?.(e);if(e.target.matches('[data-member-search]')){const q=e.target.value.trim().toLowerCase();e.target.closest('[data-member-picker]').querySelectorAll('.ga-checkboxes label').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q));}if(e.target.name==='titlePattern')refreshTitleSample();};
A.onChange=e=>{
 layoutChange?.(e);
 if(e.target.closest('[data-member-picker]'))updateMemberPicker(e.target);
 if(e.target.name?.startsWith('permission:')){readNode();syncPermissionHeader();}
 if(e.target.closest('#oa-settings')){
  const name=e.target.name;
  if(name.startsWith('permissionExport:')&&e.target.checked){const group=e.target.closest('[data-permission]');group.querySelector('[name="permissionView:'+group.dataset.permission+'"]').checked=true;group.querySelectorAll('input[type=checkbox]').forEach(PCUI.syncControl);captureAdvanced(draft());}
  if(name.startsWith('permissionView:')&&!e.target.checked){const group=e.target.closest('[data-permission]');group.querySelector('[name="permissionExport:'+group.dataset.permission+'"]').checked=false;group.querySelectorAll('input[type=checkbox]').forEach(PCUI.syncControl);captureAdvanced(draft());}
  if(['allowWithdraw','self','opinionRequired','titleMode','summaryMode'].includes(name))A.render();
 }
 if(e.target.name==='summaryFields'&&e.target.closest('.oa-summary-drawer')){summaryDraft=orderedSelection(summaryDraft,[...document.querySelectorAll('[name=summaryFields]:checked')].map(el=>el.value));drawSummaryPicker();}
};
document.addEventListener('focusin',e=>{if(e.target.closest('#oa-field-properties'))history();});
})();

;
/* The form designer shares the approval lifecycle and loads only for rules. */
window.PCModules['group-approval-designer']=window.PCModules['group-approval'];
